# === LOGO mặc định (base64) ===
LOGO_BASE64 = """

"""

class LogoPosition(Enum):
    TOP_LEFT = 1
    TOP_RIGHT = 2
    BOTTOM_LEFT = 3
    BOTTOM_RIGHT = 4
    CENTER = 5

def put_logo_on_image(image, logo, logo_size, margin=(10,10), position_map:LogoPosition=LogoPosition.BOTTOM_LEFT):
    
    img = Image.fromarray(image)
    logo_img = Image.fromarray(logo)
    iw, ih = img.size
    lw, lh = logo_img.size
    scale = min(logo_size[0] / lw, logo_size[1] / lh)
    logo_size = (int(lw * scale), int(lh * scale))
    logo_img = logo_img.resize(logo_size, Image.ANTIALIAS)
    if position_map == LogoPosition.TOP_LEFT:
        position = (margin[0], margin[1])
    elif position_map == LogoPosition.TOP_RIGHT:
        position = (iw - lw - margin[0], margin[1])
    elif position_map == LogoPosition.BOTTOM_LEFT:
        position = (margin[0], ih - lh - margin[1])
    elif position_map == LogoPosition.BOTTOM_RIGHT:
        position = (iw - lw - margin[0], ih - lh - margin[1])
    elif position_map == LogoPosition.CENTER:
        position = ((iw - lw) // 2, (ih - lh) // 2)
    else:
        position = (margin[0], ih - lh - margin[1])  # Default to BOTTOM_LEFT
    img.paste(logo_img, position, logo_img.convert("RGBA"))
    image = np.array(img)
    return image

def get_default_logo():
    return base64.b64decode(LOGO_BASE64)

def apply_random_kenburns(clip, max_zoom=0.10, max_pan=120):
    """
    Áp dụng 1 hiệu ứng Ken Burns ngẫu nhiên cho clip:
    - zoom_in, zoom_out
    - pan trái→phải / phải→trái / trên→dưới / dưới→trên
    - zoom + pan kết hợp
    """
    modes = [
        "none",
        "zoom_in", "zoom_out",
        "pan_lr", "pan_rl", "pan_tb", "pan_bt",
        "zoom_pan_lr", "zoom_pan_rl", "zoom_pan_tb", "zoom_pan_bt",
    ]
    mode = random.choice(modes)
    d = max(clip.duration, 1e-6)

    # scale(t): hệ số phóng
    if mode in ["zoom_in", "zoom_pan_lr", "zoom_pan_rl", "zoom_pan_tb", "zoom_pan_bt"]:
        clip = clip.resize(lambda t: 1.0 + max_zoom * (t / d))
    elif mode == "zoom_out":
        clip = clip.resize(lambda t: 1.0 + max_zoom * (1.0 - t / d))
    # else: "none" => không resize

    # position(t): pan theo thời gian (cần resize>1 mới thấy crop đẹp)
    if mode in ["pan_lr", "zoom_pan_lr"]:
        clip = clip.set_position(lambda t: (-max_pan * (t / d), "center"))
    elif mode in ["pan_rl", "zoom_pan_rl"]:
        clip = clip.set_position(lambda t: (-max_pan * (1.0 - t / d), "center"))
    elif mode in ["pan_tb", "zoom_pan_tb"]:
        clip = clip.set_position(lambda t: ("center", -max_pan * (t / d)))
    elif mode in ["pan_bt", "zoom_pan_bt"]:
        clip = clip.set_position(lambda t: ("center", -max_pan * (1.0 - t / d)))

    return clip


class VideoGenerator:
    def __init__(self, logo_image_path):
        if not os.path.exists(logo_image_path):
            raise ValueError(f"❌ Không tìm thấy file logo: {logo_image_path}")
        self.logo_image_path:str = logo_image_path
        self.use_default_logo = (not self.logo_image_path or self.logo_image_path is None or self.logo_image_path == "")
        self.temp_dir = "temp_processed"

    @staticmethod
    def _extract_number(filename):
        match = re.search(r'\\d+', filename)
        return int(match.group()) if match else -1

    def _make_blurred_background(self, image_path, target_width=1080, ratio_aspect = (9, 16)):
        img = cv2.imread(image_path)
        if img is None:
            print(f"⚠️ Không thể đọc file ảnh: {image_path}")
            return None, None

        h, w, _ = img.shape
        target_h = int(target_width * ratio_aspect[1] / ratio_aspect[0])
        target_size = (target_width, target_h)

        scale = min(target_width / w, target_h / h)
        new_w, new_h = int(w * scale), int(h * scale)
        resized_img = cv2.resize(img, (new_w, new_h))

        background = cv2.resize(img, target_size)
        background = cv2.GaussianBlur(background, (101, 101), 0)

        x_offset = (target_width - new_w) // 2
        y_offset = (target_h - new_h) // 2
        background[y_offset:y_offset+new_h, x_offset:x_offset+new_w] = resized_img

        temp_path = os.path.join(self.temp_dir, os.path.basename(image_path))
        cv2.imwrite(temp_path, background)
        return temp_path, background, (x_offset, y_offset, new_w, new_h)

    def _cleanup_temp_dir(self):
        if os.path.exists(self.temp_dir):
            shutil.rmtree(self.temp_dir)
            print("🗑️  Đã dọn dẹp thư mục tạm.")

    def create_video(self, image_folder, output_path, total_duration=30, logo_size=(150, 150)):
        valid_ext = (".jpg", ".jpeg", ".png", ".bmp")
        if not os.path.isdir(image_folder):
            print(f"❌ Thư mục ảnh không tồn tại: {image_folder}")
            return

        image_files = sorted(
            [os.path.join(image_folder, f) for f in os.listdir(image_folder) if f.lower().endswith(valid_ext)],
            key=lambda x: self._extract_number(os.path.basename(x))
        )

        if len(image_files) < 7:
            print(f"ℹ️  Đặt logo vào từng ảnh trong thư mục '{os.path.basename(image_folder)}' vì có ít hơn 7 ảnh.")
            out_folder = image_folder
            os.makedirs(out_folder, exist_ok=True)
            for img_path in image_files:
                _, img, _  = self._make_blurred_background(img_path, target_width=1080, ratio_aspect=(4,5)) 
                if img is None:
                    print(f"⚠️ Không thể đọc file ảnh: {img_path}")
                    continue
                if self.use_default_logo:
                    logo_data = get_default_logo()
                    nparr = np.frombuffer(logo_data, np.uint8)
                    logo_img = cv2.imdecode(nparr, cv2.IMREAD_UNCHANGED)
                else:
                    logo_img = cv2.imread(self.logo_image_path, cv2.IMREAD_UNCHANGED)
                    if logo_img is None:
                        print(f"❌ Không thể đọc file logo: {self.logo_image_path}")
                        return
                
                img_with_logo = put_logo_on_image(img, logo_img, margin=(10,10), position_map=LogoPosition.BOTTOM_LEFT)
                out_path = os.path.join(out_folder, os.path.basename(img_path))
                cv2.imwrite(out_path, img_with_logo)
                print(f"✅ Đã thêm logo vào ảnh: {out_path}")
            return

        print(f"▶️  Bắt đầu xử lí {len(image_files)} ảnh từ thư mục '{os.path.basename(image_folder)}'...")

        # --- cấu hình transition ---
        # crossfade sẽ được random cho từng "khe" giữa hai ảnh
        # ta tính d_img sao cho tổng ~ total_duration
        # Tổng = n * d_img - sum(transitions)
        num = len(image_files)
        # tạo dàn transition ngẫu nhiên trước để bù đúng tổng thời lượng
        transitions = [random.uniform(0.4, 0.8) for _ in range(max(0, num - 1))]
        total_overlap = sum(transitions)
        duration_per_image = (total_duration + total_overlap) / num  # bù chồng lấn
        
        os.makedirs(self.temp_dir, exist_ok=True)
        try:
            duration_per_image = total_duration / len(image_files)
            clips = []
            positions = []

            for img_path in image_files:
                processed_path,_, content_box = self._make_blurred_background(img_path)
                if processed_path:
                    clip = ImageClip(processed_path).set_duration(duration_per_image)

                    # Ken Burns ngẫu nhiên cho từng ảnh
                    clip = apply_random_kenburns(clip, max_zoom=0.08, max_pan=100)

                    clips.append(clip)
                    positions.append(content_box)
            
            if not clips:
                print("❌ Không tạo được clip nào từ các ảnh đã cho.")
                return

            # Áp dụng crossfade ngẫu nhiên:
            clips_with_xfade = [clips[0]]
            for i, c in enumerate(clips[1:], start=1):
                t = transitions[i - 1]
                clips_with_xfade.append(c.crossfadein(t))


            slideshow = concatenate_videoclips(clips_with_xfade, method="compose")
            if (self.use_default_logo):
                logo_img = (ImageClip(get_default_logo(), transparent=True)
                        .resize(height=logo_size[1])
                        .set_duration(total_duration))
            else:
                logo_img = (ImageClip(self.logo_image_path, transparent=True)
                            .resize(height=logo_size[1])
                            .set_duration(total_duration))

            x_offset, y_offset, _, content_h = positions[0]
            logo_position = (x_offset + 10, y_offset + content_h - logo_size[1] - 10)
            logo_img = logo_img.set_position(logo_position)

            final = CompositeVideoClip([slideshow, logo_img], size=(1080, 1920)).set_duration(total_duration)
            final.write_videofile(output_path, fps=30, codec="libx264", bitrate="6000k", audio=False, logger=None)
            print(f"✅ Video đã được tạo thành công: {output_path}")

        finally:
            self._cleanup_temp_dir()

def main_single():
    print("🎬 Tạo video 9:16 từ một thư mục ảnh và overlay logo")
    images_folder = input("Thư mục chứa ảnh: ").strip()
    logo_image_path = input("Đường dẫn file logo: ").strip()
    output_path = input("Tên video đầu ra (mặc định: final_output.mp4): ").strip()
    
    if not output_path:
        output_path = "final_output.mp4"
    if not os.path.isabs(output_path):
         output_path = os.path.join(os.path.dirname(images_folder) or '.', output_path)

    try:
        generator = VideoGenerator(logo_image_path)
        generator.create_video(images_folder, output_path)
    except ValueError as e:
        print(e)


def main_folder():
    print("🗂️  Tạo hàng loạt video 9:16 từ các thư mục con")
    base_folder = input("Thư mục cha chứa các thư mục ảnh: ").strip()
    logo_image_path = input("Đường dẫn file logo: ").strip()
    
    if not os.path.isdir(base_folder):
        print("❌ Thư mục cha không tồn tại.")
        return

    try:
        generator = VideoGenerator(logo_image_path)
        subfolders = [f.path for f in os.scandir(base_folder) if f.is_dir()]
        print(f"Tìm thấy {len(subfolders)} thư mục con để xử lý.")
        for folder in subfolders:
            output_filename = f"{os.path.basename(folder)}.mp4"
            output_path = os.path.join(base_folder, output_filename)
            generator.create_video(folder, output_path)
    except ValueError as e:
        print(e)


if __name__ == "__main__":
    print("Chọn chế độ chạy:")
    print("1. Xử lý một thư mục duy nhất")
    print("2. Xử lý hàng loạt thư mục con trong một thư mục cha")
    choice = input("Lựa chọn của bạn (1 hoặc 2): ").strip()

    if choice == '1':
        main_single()
    elif choice == '2':
        main_folder()
    else:
        print("Lựa chọn không hợp lệ.")
